CREATE DATABASE IF NOT EXISTS internet_cafe_v2_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE internet_cafe_v2_db;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(20) NOT NULL UNIQUE,role ENUM('admin','user') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE packages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,hourly_rate DECIMAL(10,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE gaming_stations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,station_code VARCHAR(30) NOT NULL UNIQUE,package_id BIGINT UNSIGNED NOT NULL,zone_name VARCHAR(100) NOT NULL,status ENUM('available','reserved','in_use','maintenance') NOT NULL DEFAULT 'available',specs_info VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT stations_package_fk FOREIGN KEY(package_id) REFERENCES packages(id)) ENGINE=InnoDB;
CREATE TABLE session_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_code VARCHAR(50) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,station_id BIGINT UNSIGNED NOT NULL,minutes_used INT UNSIGNED NOT NULL DEFAULT 0,total_amount DECIMAL(10,2) NOT NULL DEFAULT 0,status ENUM('reserved','active','completed','cancelled','expired') NOT NULL,reserved_at DATETIME NOT NULL,started_at DATETIME NULL,ended_at DATETIME NULL,hourly_rate DECIMAL(10,2) NOT NULL,free_minutes_used INT UNSIGNED NOT NULL DEFAULT 0,planned_minutes SMALLINT UNSIGNED NULL,quoted_amount DECIMAL(10,2) NOT NULL DEFAULT 0,prepaid_amount DECIMAL(10,2) NOT NULL DEFAULT 0,paid_at DATETIME NULL,scheduled_end_at DATETIME NULL,refund_amount DECIMAL(10,2) NOT NULL DEFAULT 0,refund_status ENUM('none','pending','paid') NOT NULL DEFAULT 'none',refunded_at DATETIME NULL,refunded_by BIGINT UNSIGNED NULL,INDEX sessions_refund_status(refund_status,ended_at),CONSTRAINT sessions_refunded_by_fk FOREIGN KEY(refunded_by) REFERENCES users(id),INDEX sessions_station_status(station_id,status),INDEX sessions_user_status(user_id,status),CONSTRAINT sessions_user_fk FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT sessions_station_fk FOREIGN KEY(station_id) REFERENCES gaming_stations(id)) ENGINE=InnoDB;
